INSERT INTO TODO_ITEM (
    TODO_ID
   ,MEMBER_ID
   ,COMPANY_ID
   ,JOB_ID
   ,TITLE
   ,PRIORITY
   ,DUE_DATE
   ,STATUS
   ,MEMO
   ,COMPLETED_AT
   ,CREATED_AT
   ,UPDATED_AT
) VALUES (
    #{todoId}
   ,#{memberId}
   ,#{companyId,jdbcType=NUMERIC}
   ,#{jobId,jdbcType=NUMERIC}
   ,#{title}
   ,#{priority}
   ,#{dueDate,jdbcType=DATE}
   ,#{status}
   ,#{memo,jdbcType=CLOB}
   ,CASE
            WHEN #{status} = 'DONE' THEN SYSTIMESTAMP
        END
   ,SYSTIMESTAMP
   ,SYSTIMESTAMP
)

mapper.update:
UPDATE  TODO_ITEM
SET     COMPANY_ID   = #{companyId,jdbcType=NUMERIC}
       ,JOB_ID       = #{jobId,jdbcType=NUMERIC}
       ,TITLE        = #{title}
       ,PRIORITY     = #{priority}
       ,DUE_DATE     = #{dueDate,jdbcType=DATE}
       ,STATUS       = #{status}
       ,MEMO         = #{memo,jdbcType=CLOB}
       ,COMPLETED_AT = CASE
            WHEN #{status} = 'DONE' THEN NVL(COMPLETED_AT, SYSTIMESTAMP)
            ELSE NULL
        END
       ,UPDATED_AT   = SYSTIMESTAMP
WHERE   MEMBER_ID = #{memberId}
AND     TODO_ID = #{todoId}

